import static org.junit.jupiter.api.Assertions.assertEquals;

import com.wolinski.shop.money.Money;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.api.Test;

class OrderServiceExpireStaleTest {

    // 2026-10-31 02:00 in Warsaw (CET, UTC+1)
    private static final Instant NOW = Instant.parse("2026-10-31T01:00:00Z");

    @Test
    void cancelsPlacedOrdersOlderThanThirtyDaysOnly() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, Clock.fixed(NOW, ZoneOffset.UTC));

        // Warsaw 2026-09-30 23:30 (CEST): 31 days ago -> cancelled
        Order oldPlaced = place(repository, Instant.parse("2026-09-30T21:30:00Z"));
        // Warsaw 2026-10-01 12:00: exactly 30 days ago -> kept
        Order borderPlaced = place(repository, Instant.parse("2026-10-01T10:00:00Z"));
        // Warsaw 2026-10-30: recent -> kept
        Order recentPlaced = place(repository, Instant.parse("2026-10-30T10:00:00Z"));
        // Old but already confirmed -> kept
        Order oldConfirmed = place(repository, Instant.parse("2026-09-01T10:00:00Z"));
        oldConfirmed.changeStatus("CONFIRMED");

        int expired = service.expireStale();

        assertEquals(1, expired);
        assertEquals("CANCELLED", oldPlaced.status());
        assertEquals("PLACED", borderPlaced.status());
        assertEquals("PLACED", recentPlaced.status());
        assertEquals("CONFIRMED", oldConfirmed.status());
    }

    @Test
    void returnsZeroWhenNothingIsStale() {
        OrderRepository repository = new OrderRepository();
        OrderService service = new OrderService(repository, Clock.fixed(NOW, ZoneOffset.UTC));
        place(repository, Instant.parse("2026-10-30T10:00:00Z"));

        assertEquals(0, service.expireStale());
    }

    private static Order place(OrderRepository repository, Instant placedAt) {
        Order order = new Order(java.util.UUID.randomUUID().toString(), "c-1", Money.pln(1000), placedAt);
        repository.save(order);
        return order;
    }
}
}

